import "server-only";
import { db } from "@/lib/db";
import { AppError } from "@/lib/errors";

import { lockUsageOwner, repairUsageCounters } from "@/lib/usage-ledger";
import { preserveAcceptedSend } from "@/lib/usage-backfill";

export async function clearCompletedHistory(userId: string) {
  return db.$transaction(
    async (tx) => {
      // Serialize with delivery claims, new campaigns, and account deletion.
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
      const owner = await lockUsageOwner(tx, userId);
      // Acquire bucket locks before locking or deleting Send rows.
      await repairUsageCounters(owner);
      const user = await tx.user.findFirst({
        where: { id: userId, deletionRequestedAt: null },
        select: { id: true },
      });
      if (!user) throw new AppError("Account unavailable.");
      // Lock eligible rows while transferring quota and duplicate evidence.
      // A delivery resolving concurrently is either included or left for next time.
      const completed = await tx.$queryRaw<
        {
          id: string;
          recipientEmail: string;
          createdAt: Date;
          sentAt: Date | null;
          status: string;
        }[]
      >`
        SELECT s.id, s."recipientEmail", s."createdAt", s."sentAt", s.status
        FROM "Send" s JOIN "Campaign" c ON c.id = s."campaignId"
        WHERE c."userId" = ${userId} AND s.status IN ('SENT', 'REPLIED', 'FAILED', 'CANCELLED')
          AND s."deliveryState" NOT IN ('ATTEMPTING', 'UNCERTAIN')
        FOR UPDATE OF s`;
      const receipts = completed.filter(
        (s) => (s.status === "SENT" || s.status === "REPLIED") && s.sentAt,
      );
      const receiptRows = [];
      for (const send of receipts) {
        const deliveryKey = await preserveAcceptedSend(owner, send.id);
        receiptRows.push({
          userId,
          recipientEmail: send.recipientEmail,
          createdAt: send.createdAt,
          sentAt: send.sentAt!,
          deliveryKey,
        });
      }
      if (receiptRows.length)
        await tx.deliveryReceipt.createMany({
          data: receiptRows,
          skipDuplicates: true,
        });
      // Active campaigns still need their original size and role snapshots for
      // downgrade checks. Hide and redact completed rows until the campaign is
      // terminal, preserving only the policy/delivery evidence already retained.
      const activeCampaigns = await tx.campaign.findMany({
        where: {
          userId,
          sends: {
            some: {
              OR: [
                { status: "QUEUED" },
                { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
              ],
            },
          },
        },
        select: { id: true },
      });
      const activeIds = activeCampaigns.map((campaign) => campaign.id);
      const retained = await tx.send.updateMany({
        where: {
          id: { in: completed.map((send) => send.id) },
          campaign: { userId },
          campaignId: { in: activeIds },
          historyDeletedAt: null,
        },
        data: {
          historyDeletedAt: new Date(),
          subject: "",
          body: "",
          recipientName: "",
          recipientCompany: "",
          templateName: "",
        },
      });
      const cleared = await tx.send.deleteMany({
        where: {
          id: { in: completed.map((s) => s.id) },
          campaign: { userId },
          campaignId: { notIn: activeIds },
        },
      });
      // Retain campaign keys so replaying an old submission cannot send again.
      await tx.campaign.updateMany({
        where: { userId, sends: { none: {} } },
        data: { role: "", attachmentId: null },
      });
      return cleared.count + retained.count;
    },
    { timeout: 10000 },
  );
}
